import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col } from "react-bootstrap";

function Dashboard() {
  const [stats, setStats] = useState({
    capacity: "Loading...", revenue: "Loading...", errors: 0, followers: 0
  });

  const [chartData, setChartData] = useState({
    labels: [],
    series: [] 
  });

  useEffect(() => {
    // ดึงตัวเลขการ์ด
    fetch('http://localhost:3000/api/dashboard-stats')
      .then(res => res.json())
      .then(data => setStats(data))
      .catch(err => console.error("Stats Error:", err));

    // ฟังก์ชันดึงข้อมูลกราฟ
    const loadData = () => {
        fetch('http://localhost:3000/api/chart-data')
        .then(res => res.json())
        .then(data => {
            console.log("Real-time Chart Data:", data); // ตรวจสอบค่าใน Console
            setChartData({
                labels: data.labels,
                series: data.series
            });
        })
        .catch(err => console.error("Chart Error:", err));
    };

    loadData();
    const interval = setInterval(loadData, 30000); // อัปเดตทุก 30 วินาที
    return () => clearInterval(interval);
  }, []);

  return (
    <Container fluid>
      {/* ... (ส่วน Card ด้านบนเหมือนเดิม) ... */}

      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">Passenger Density (Dynamic Stations)</Card.Title>
              <p className="card-category">Real-time data from database</p>
            </Card.Header>
            <Card.Body>
              <div className="ct-chart">
                <ChartistGraph
                  data={chartData}
                  type="Line"
                  options={{
                    low: 0,
                    showArea: false,
                    height: "245px",
                    axisX: { 
                        showGrid: false,
                        labelInterpolationFnc: (value, index) => index % 2 === 0 ? value : null // แสดง label ทุก 1 ชม.
                    },
                    lineSmooth: true,
                    showLine: true,
                    showPoint: true, // แสดงจุดข้อมูล
                    fullWidth: true,
                    chartPadding: { right: 50 }
                  }}
                />
              </div>
            </Card.Body>
            <Card.Footer>
              <div className="legend">
                {/* สีจะเรียงตามลำดับ Series ที่ส่งมาจาก API */}
                <i className="fas fa-circle text-info"></i> ป้าย 1 &nbsp;
                <i className="fas fa-circle text-danger"></i> ป้าย 2 &nbsp;
                <i className="fas fa-circle text-warning"></i> ป้าย 3 &nbsp;
                <i className="fas fa-circle" style={{ color: '#9322DD' }}></i> ป้าย 4
              </div>
              <hr />
              <div className="stats">
                <i className="fas fa-history"></i> Updated automatically every 30s
              </div>
            </Card.Footer>
          </Card>
        </Col>
      </Row>
    </Container>
  );
}

export default Dashboard;
